  ('e2000000-0000-4000-b000-0000000027bd', 'e2000000-0000-4000-a000-0000000003f9', 3, 'As modificações incorporadas ao MMA têm por finalidade aprimorar as técnicas das diferentes artes marciais, favorecendo o desenvolvimento da modalidade enquanto defesa pessoal.', false),
  ('e2000000-0000-4000-b000-0000000027be', 'e2000000-0000-4000-a000-0000000003f9', 4, 'As transformações do MMA visam delimitar a violência das lutas, preservando a integridade dos atletas e enquadrando a modalidade no formato do esporte de espetáculo.', true),
