  ('e2000000-0000-4000-b000-000000002865', 'e2000000-0000-4000-a000-00000000040a', 1, 'Caracterização das opiniões relativas a determinados gêneros, considerados os mais representativos da brasilidade, como meros estereótipos.', false),
  ('e2000000-0000-4000-b000-000000002866', 'e2000000-0000-4000-a000-00000000040a', 2, 'Uso de estrangeirismos, como rock, funk e gospel, para compor um estilo próximo ao leitor, em sintonia com o ataque aos nacionalistas.', false),
  ('e2000000-0000-4000-b000-000000002867', 'e2000000-0000-4000-a000-00000000040a', 3, 'Ironia com relação ao apego a opiniões superadas, tomadas como expressão de conservadorismo e anacronismo, com o uso das designações “império” e “baluarte”.', false),
  ('e2000000-0000-4000-b000-000000002868', 'e2000000-0000-4000-a000-00000000040a', 4, 'Contraposição a impressões fundadas em elitismo e preconceito, com a alusão a artistas de renome para melhor demonstrar a consolidação da mudança do gosto musical popular.', false),
  ('e2000000-0000-4000-b000-00000000286e', 'e2000000-0000-4000-a000-00000000040b', 0, 'Afirma, com a frase “Queremos seu talento exatamente como ele é”, que qualquer pessoa com talento pode fazer parte da equipe.', false),
  ('e2000000-0000-4000-b000-00000000286f', 'e2000000-0000-4000-a000-00000000040b', 1, 'Apresenta como estratégia a formação de um perfil por meio de perguntas direcionadas, o que dinamiza a interação texto-leitor.', true),
  ('e2000000-0000-4000-b000-000000002870', 'e2000000-0000-4000-a000-00000000040b', 2, 'Utiliza a descrição da empresa como argumento principal, pois atinge diretamente os interessados em informática.', false),
  ('e2000000-0000-4000-b000-000000002871', 'e2000000-0000-4000-a000-00000000040b', 3, 'Usa estereótipo negativo de uma figura conhecida, o nerd, pessoa introspectiva e que gosta de informática.', false),
