  ('e2000000-0000-4000-b000-00000000288f', 'e2000000-0000-4000-a000-00000000040e', 3, 'A pronúncia e o vocabulário são aspectos identificadores da classe social a que pertence o falante.', false),
  ('e2000000-0000-4000-b000-000000002890', 'e2000000-0000-4000-a000-00000000040e', 4, 'O modo de falar específico de pessoas de diferentes faixas etárias é frequente em todas as regiões.', false),
  ('e2000000-0000-4000-b000-000000002896', 'e2000000-0000-4000-a000-00000000040f', 0, 'A forma do soneto, os versos metrificados, a presença de rimas e o vocabulário requintado, além do ceticismo, que antecipam conceitos estéticos vigentes no Modernismo.', false),
  ('e2000000-0000-4000-b000-000000002897', 'e2000000-0000-4000-a000-00000000040f', 1, 'O empenho do eu lírico pelo resgate da poesia simbolista, manifesta em metáforas como “Monstro de escuridão e rutilância” e “influência má dos signos do zodíaco”.', false),
  ('e2000000-0000-4000-b000-000000002898', 'e2000000-0000-4000-a000-00000000040f', 2, 'A seleção lexical emprestada ao cientificismo, como se lê em “carbono e amoníaco”, “epigênesis da infância” e “frialdade inorgânica”, que restitui a visão naturalista do homem.', false),
