  ('e2000000-0000-4000-b000-00000000289a', 'e2000000-0000-4000-a000-00000000040f', 4, 'A ênfase no processo de construção de uma poesia descritiva e ao mesmo tempo filosófica, que incorpora valores morais e científicos mais tarde renovados pelos modernistas.', false),
  ('e2000000-0000-4000-b000-0000000028a0', 'e2000000-0000-4000-a000-000000000410', 0, 'Filosófico, pois reflete sobre as mazelas sofridas pelos vizinhos.', false),
