  ('e2000000-0000-4000-b000-0000000028e6', 'e2000000-0000-4000-a000-000000000417', 0, 'Uma referência ao contexto, “trânsito no feriadão”, esclarecendo-se o referente tanto do texto de Iotti quanto da obra de Picasso.', false),
  ('e2000000-0000-4000-b000-0000000028e7', 'e2000000-0000-4000-a000-000000000417', 1, 'Uma referência ao tempo presente, com o emprego da forma verbal “é”, evidenciando-se a atualidade do tema abordado tanto pelo pintor espanhol quanto pelo chargista brasileiro.', false),
  ('e2000000-0000-4000-b000-0000000028e8', 'e2000000-0000-4000-a000-000000000417', 2, 'Um termo pejorativo, “trânsito”, reforçando-se a imagem negativa de mundo caótico presente tanto em Guernica quanto na charge.', false),
  ('e2000000-0000-4000-b000-0000000028e9', 'e2000000-0000-4000-a000-000000000417', 3, 'Uma referência temporal, “sempre”, referindo-se à permanência de tragédias retratadas tanto em Guernica quanto na charge.', false),
  ('e2000000-0000-4000-b000-0000000028ea', 'e2000000-0000-4000-a000-000000000417', 4, 'Uma expressão polissêmica, “quadro dramático”, remetendo-se tanto à obra pictórica quanto ao contexto do trânsito brasileiro.', true),
