  ('e2000000-0000-4000-b000-000000003a49', 'e2000000-0000-4000-a000-0000000005d4', 1, 'Garantia de ascensão social dos jovens pela carreira de jogador de futebol.', false),
  ('e2000000-0000-4000-b000-000000003a4a', 'e2000000-0000-4000-a000-0000000005d4', 2, 'Falta de investimento dos clubes para que os atletas possam atuar profissionalmente e viver do futebol.', false),
  ('e2000000-0000-4000-b000-000000003a4b', 'e2000000-0000-4000-a000-0000000005d4', 3, 'Investimento reduzido dos atletas profissionais em sua formação escolar, gerando frustração e desilusão profissional no esporte.', false),
