  ('e2000000-0000-4000-b000-000000003a52', 'e2000000-0000-4000-a000-0000000005d5', 0, '“A língua portuguesa é um verdadeiro desafio para quem escreve.”', false),
  ('e2000000-0000-4000-b000-000000003a53', 'e2000000-0000-4000-a000-0000000005d5', 1, '“Um Camões e outros iguais não bastaram para nos dar para sempre uma herança de língua já feita.”', true),
  ('e2000000-0000-4000-b000-000000003a54', 'e2000000-0000-4000-a000-0000000005d5', 2, '“Todos nós que escrevemos estamos fazendo do túmulo do pensamento alguma coisa que lhe dê Vida.”', false),
  ('e2000000-0000-4000-b000-000000003a55', 'e2000000-0000-4000-a000-0000000005d5', 3, '“Mas não falei do encantamento de lidar com uma língua que não foi aprofundada.”', false),
  ('e2000000-0000-4000-b000-000000003a56', 'e2000000-0000-4000-a000-0000000005d5', 4, '“Eu até queria não ter aprendido outras línguas: só para que a minha abordagem do português fosse Virgem e límpida.”', false),
