  ('e2000000-0000-4000-a000-0000000004bf', 'ENEM-2015-110', 15, 438, 'enem', 3, 2, 2015, 'multiple_choice', 'Arte e cultura', '![](conteudo/enem/2015/110-6af2efde.webp)

